/* 9_textos_s_vs_e.sql - SOLO LECTURA. Para cada fila S distinta de E saca el texto
   en S, en E y en D (aleman, original de muchos objetos SAP), una linea por idioma:
   #tabla#clave#campo#idioma#texto     Para medir offline que hay en esas filas.
   Correr: correr_sql.bat sql\09_textos_s_vs_e.sql */
set nocount on
go
set quoted_identifier on
go
select 'inicio', getdate()
go
select convert(varchar(290), '#T100#' + rtrim(s."ARBGB") + '|' + rtrim(s."MSGNR") + '#TEXT#S#' + isnull(rtrim(s."TEXT"),'')) k from BAS.SAPSR3."T100" s noholdlock, BAS.SAPSR3."T100" e noholdlock where s."SPRSL" = 'S' and e."SPRSL" = 'E' and s."ARBGB" = e."ARBGB" and s."MSGNR" = e."MSGNR" and s."TEXT" <> e."TEXT"
