select convert(varchar(290), '#RSMPTEXTS#' + rtrim(s."PROGNAME") + '|' + rtrim(s."OBJ_TYPE") + '|' + rtrim(s."OBJ_CODE") + '|' + rtrim(s."SUB_CODE") + '|' + rtrim(s."TEXTTYPE") + '#TEXT#D#' + isnull(rtrim((select max(d."TEXT") from BAS.SAPSR3."RSMPTEXTS" d noholdlock where d."SPRSL" = 'D' and d."PROGNAME" = s."PROGNAME" and d."OBJ_TYPE" = s."OBJ_TYPE" and d."OBJ_CODE" = s."OBJ_CODE" and d."SUB_CODE" = s."SUB_CODE" and d."TEXTTYPE" = s."TEXTTYPE")),'~')) k from BAS.SAPSR3."RSMPTEXTS" s noholdlock, BAS.SAPSR3."RSMPTEXTS" e noholdlock where s."SPRSL" = 'S' and e."SPRSL" = 'E' and s."PROGNAME" = e."PROGNAME" and s."OBJ_TYPE" = e."OBJ_TYPE" and s."OBJ_CODE" = e."OBJ_CODE" and s."SUB_CODE" = e."SUB_CODE" and s."TEXTTYPE" = e."TEXTTYPE" and s."TEXT" <> e."TEXT"
go
select convert(varchar(290), '#CUS_IMGACT#' + rtrim(s."ACTIVITY") + '#TEXT#S#' + isnull(rtrim(s."TEXT"),'')) k from BAS.SAPSR3."CUS_IMGACT" s noholdlock, BAS.SAPSR3."CUS_IMGACT" e noholdlock where s."SPRAS" = 'S' and e."SPRAS" = 'E' and s."ACTIVITY" = e."ACTIVITY" and s."TEXT" <> e."TEXT"
